@media print {
  @page {
    margin: 0 !important;
    padding: 0 !important;
  }

  body {
    margin: 0 !important;
    padding: 0 !important;
  }
}

.print-format {
  margin: 0 !important;
  padding: 0 !important;
}

/* Remove Letterhead blank spacing */
.print-heading {
  display: none !important;
}

body {
  font-family: Times, Arial, sans-serif;
  margin: 0;
  padding: 0;
  color: #000;
}

.payslip-container {
  width: 750px;
  margin: 20px auto !important;
  /* Center exactly */
  border: 1px solid #000;
  padding: 0;
  /*padding-bottom : 5px;*/
}

.header>div:nth-child(1) {
  display: flex;
  align-items: flex-start;
  padding: 10px;
}

.header>div:nth-child(1) img {
  width: 160px;
  height: auto;
  margin-left: -5px;
  margin-top: -5px;
}

.header-title {
  flex: 1;
  text-align: center;
  margin-right: 60px;
  font-family: 'Times New Roman';
  /*align-content : flex-start;*/
}

.header-title h2 {
  margin: 0;
  font-size: 16px !important;
  margin-top: -5px;
  font-weight: 900;
}

.header-title p {
  margin: 2px 0;
  font-size: 10px;
  font-family: 'Times New Roman';
}

.payslip-title {
  text-align: center;
  font-weight: bold;
  padding: 3px 0;
  border-bottom: 1px solid #000;
  margin-top: -10px;
  font-size: 15px;
  font-family: 'Times New Roman';

}

/* Info section */
.info-section {
  display: flex;
  justify-content: space-between;
  /*font-size: 12px;*/
  padding: 10px;

}

.info-section {
  width: 100%;
  color: #000;
  font-family: 'Times New Roman';
  font-size: 12px;
  line-height: 0.9;
  padding: 0;
}

.info-section .info-col {
  width: 50%;
  padding-left: 5px;

}

.info-section .info-col:nth-child(1) {
  border-right: 1px solid;
}

.info-section>.info-col>.info-row {
  display: flex;
  justify-content: space-between;
  text-align: left !important;
  width: 100%;

}

.info-section .info-col .info-row>p {
  width: 50%;

  text-align: left;

}

.info-section p {
  text-align: left;
}

.tables {
  display: flex;
}

.tables table {
  width: 100%;
  height: 100%;
  border: none;
  color: #000;
  font-family: 'Times New Roman';
  border-bottom: 1px solid #000;
  border-top: 1px solid #000;
  font-size: 11px;
  padding: 0px;
}

.tables table td,
tables table th,
tables table tr {
  padding: 0;
  line-height: 1;
  font-size: 13px;
}

.tables table tr:first-child {
  border-bottom: 1px solid #000;
}

.tables table tr:last-child {
  border-top: 1px solid #000;
  font-size: 12px;
}

.tables table tr:last-child td:last-child {
  font-weight: 800;
  text-align: right;
}

.tables table tr:first-child th:nth-child(3) {
  border-right: 1px solid #000;
  text-align: right;
}

.tables table tr th:last-child {
  text-align: right;
}


.tables table tr td:nth-child(3) {
  color: #000;
  /*font-size: 14px;*/
  /*font-weight: 700;*/
  border-right: 1px solid #000;
  margin-right: 1px;
  text-align: right;
}

.tables table tr:last-child td:nth-child(3) {
  color: #000;
  border-right: none;
  margin-right: 1px;
  text-align: left;
}

.tables table tr:last-child td:nth-child(2) {
  color: #000;
  border-right: 1px solid #000;
  margin-right: 1px;
  text-align: right;
}


.tables table tr th {
  font-weight: 700;
  color: #000;
  font-size: 13px;
  text-align: center;
}

.total-row td:nth-child(2) {
  text-align: right;
}

.tables table tr td:nth-child(2),
.tables table tr th:nth-child(2) {
  text-align: right;
}

.tables table tr,
.tables table td,
.tables table th {
  padding: 6px 6px !important;
  line-height: 1.0;
  height: 20px;
  vertical-align: middle;
}

.netpay-box {
  width: 49%;

  font-weight: bold;
  font-size: 11px;
  /*padding: 10px;*/
}

.netpay-box div {
  display: flex;
  justify-content: space-between;
  font-family: 'Times New Roman';
  font-size: 12px;
}

.netpay-box div p:first-child {
  margin-left: 10px;
  font-weight: 500;
  margin-bottom: 5px;
}

.netpay-box div:nth-child(2) {
  dipslay: none !important;
  text-align: right;
  font-weight: 800;
  margin-right: 3px;
}

.netpay-box div:last-child {
  margin-left: 10px;
  font-family: 'Times New Roman';
  font-weight: 500;
  font-style: italic;
}

.netpay-box div p:last-child {
  text-align: right;
  font-weight: 800;
  margin-right: 3px;
}

.employee {
  margin-left: 0px;
  margin-top: 10px;
  border-top: 1px solid #000;
  width: 100%;
  display: flex;
  justify-content: flex-start;
  font-family: 'Times New Roman';
  font-size: 13px;
}

.employee>div>p:last-child {
  text-align: right;
  font-weight: 800;
  margin-right: 3px;
}

.employee div {
  border-right: 1px solid #000;
  width: 50%;
  display: flex;
  justify-content: space-between;

}

.employee div p:last-child {
  text-align: right;
  font-weight: 800;
}

.employee div p:first-child {
  text-align: right;
  font-weight: 600;
  margin-left: 10px;

}


.footer {
  text-align: center;
  margin-top: -10px;
  font-size: 12px;
  font-family: 'Times New Roman';
}

/* =========================================================
   SYSTEM PDF FIXES
   ========================================================= */

* {
    box-sizing: border-box !important;
}

@page {
    size: A4;
    margin: 10mm;
}

body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    margin: 0;
    padding: 0;
}


/* =========================================================
   MAIN CONTAINER
   ========================================================= */

.container {
    width: 200mm;
    max-width: 100%;
    margin: 0 auto;
    border: 1px solid #000;
    padding: 0 !important;
    overflow: hidden;
}


/* =========================================================
   GENERAL TABLE STYLES
   ========================================================= */

table {
    width: 100%;
    max-width: 100%;
    border-collapse: collapse;
    margin-top: 5px;
}

td,
th {
    border: 1px solid #000;
    padding: 4px;
    font-size: 11px;
    word-wrap: break-word;
}


/* =========================================================
   PRINT SETTINGS
   ========================================================= */

@media print {

    body {
        margin: 0 !important;
        zoom: 0.95;
    }

    .terms {
        border-right: 1px solid #000 !important;
        border-left: 1px solid #000 !important;
    }

}


/* =========================================================
   LETTERHEAD / HEADER
   ========================================================= */

.right.top,
.right.top tr,
.right.top td {
    border: none !important;
    border-left: none !important;
}

.top-table,
.top-table td,
.top-table th {
    border: none !important;
    font-size: 15px !important;
    font-weight: 800 !important;
    padding: 2px !important;
}

.header {
    text-align: center;
}

.header img {
    height: 90px !important;
    width: 90px !important;
}

.header h3 {
    background: #017bcf;
    border-radius: 5px;
    padding: 5px;
    color: #fff;
    font-weight: 800;
    text-transform: uppercase;
    word-spacing: 2px;
    letter-spacing: 2px;
    box-shadow: 0 0 4px #888;
}

.header p {
    font-size: 12px;
    font-weight: 600;
    margin: 0 auto;
    line-height: 13px;
    width: 80%;
    margin-top: 3px;
}

.row2 {
    border-bottom: 1px solid #000;
}


/* =========================================================
   CLIENT / VENDOR DETAILS
   ========================================================= */

.client-vendor-table {
    width: 100% !important;
    border-collapse: collapse !important;
    table-layout: fixed;
    margin-top: 0 !important;
    border-top:none;
}


/* Section headings */

.client-vendor-table .section-title {
    background: #017bcf !important;
    color: #fff !important;
    text-align: center !important;
    font-weight: bold !important;
    font-size: 12px !important;
    padding: 5px !important;
    border-top:none!important;
}


/* Labels */

.client-vendor-table .label {
    font-weight: normal;
    padding: 5px !important;
    vertical-align: middle;
}


/* Values */

.client-vendor-table .value {
    padding: 5px !important;
    vertical-align: middle;
}


/* Left outside border */

.client-vendor-table tr td:first-child,
.client-vendor-table tr th:first-child {
    border-left: none !important;
}


/* Right outside border */

.client-vendor-table tr td:last-child,
.client-vendor-table tr th:last-child {
    border-right: none !important;
}


/* Description row */

.client-vendor-table .last-row td {
    border-bottom: none !important;
    padding: 6px !important;
}


/* Description */

.client-vendor-table dl {
    margin: 0 !important;
}

.client-vendor-table dt {
    margin: 0 !important;
}

.client-vendor-table dd {
    margin: 3px 0 0 10px !important;
}


/* =========================================================
   OLD CLIENT TABLE - DISABLED / NOT USED
   ========================================================= */

/*
.clients-table {
    border-left: none !important;
    border-right: none !important;
    border-bottom: none !important;
}

.clients-table td:nth-child(1) {
    border-left: none !important;
}

.clients-table td:nth-child(4) {
    border-right: none !important;
}
*/


/* =========================================================
   GENERAL ALIGNMENT
   ========================================================= */

.right {
    text-align: right;
}


/* =========================================================
   CONTACT STYLES
   Kept only if used elsewhere
   ========================================================= */

.contact-title {
    background: #017bcf;
    color: #fff;
    text-align: center;
    font-weight: bold;
    vertical-align: middle;
}

.contact-details td:nth-child(4),
.contact-details2 td:nth-child(3) {
    background: #ffffa7;
    border-right: none !important;
}


/* =========================================================
   ITEMS TABLE
   ========================================================= */

.items {
    width: 100%;
    border: none !important;
    border-collapse: collapse;
}

.items thead {
    display: table-header-group;
}

.items tfoot {
    display: table-footer-group;
}

.items tr {
    page-break-inside: avoid;
}


/* Items header */

.items thead th {
    background: #017bcf !important;
    color: #fff !important;
    font-weight: bold;
}


/* First column - remove left outer border */

.items tr td:first-child,
.items tr th:first-child {
    border-left: none !important;
}


/* Last column - remove right outer border */

.items tr td:last-child,
.items tr th:last-child {
    border-right: none !important;
}


/* =========================================================
   FINAL TOTAL SECTION
   ========================================================= */

.final-total td {
    padding: 4px !important;
    vertical-align: middle !important;
}

.last-content {
    background: #ffffa7;
    color: #000 !important;
    text-align: center;
    vertical-align: middle !important;
}


/* Grand total */

.last-content.total {
    background: #87cefa !important;
    vertical-align: middle !important;
    text-align: center !important;
    color: #000;
    white-space: nowrap !important;
    padding: 0 !important;
}


/* Fix rogue border / background issue */

.last-content.total b {
    display: inline-block;
    background: #87cefa;
    position: relative;
    z-index: 10;
    padding: 6px 0;
    width: 100%;
}


/* =========================================================
   TOTAL / PAYMENT
   ========================================================= */

.total {
    font-weight: bold;
    text-align: right;
}

.total-label {
    text-align: right;
    font-weight: bold;
}

.payment {
    background: #ffffa7;
    font-weight: bold;
    padding: 2px;
}

.term-data {
    background: #ffffa7;
}


/* =========================================================
   TERMS & CONDITIONS
   ========================================================= */

.terms {
    margin-top: 10px;
}

.terms td,
.terms th {
    background: transparent !important;
}


/* =========================================================
   LAST ROW
   ========================================================= */

.last-row,
.last-row td {
    border-bottom: none !important;
}

.last-row td:nth-child(1) p {
    color: red;
}

.last-row td:nth-child(1) b {
    color: #000;
}


/* =========================================================
   FOOTER
   ========================================================= */

.footer td {
    vertical-align: top;
}

.signature {
    text-align: center;
    font-weight: 900;
    vertical-align: bottom;
}


/* =========================================================
   BANK DETAILS / FOOTER TABLE
   ========================================================= */

.last-row table {
    margin-top: 0 !important;
}


/* =========================================================
   PAGE BREAK CONTROL
   ========================================================= */

/*
   Do NOT apply page-break-inside: avoid to every td.
   It can break rowspan/layout behavior in PDF generation.
*/

